public with sharing class LeadImportService {

    public class ImportResult {
        public Integer successCount = 0;
        public List<Id> insertedIds = new List<Id>();
        public Map<Integer, String> errorsByIndex = new Map<Integer, String>();
    }

    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        // Default LeadSource to 'Web' where blank
        for (Lead l : leads) {
            if (String.isBlank(l.LeadSource)) {
                l.LeadSource = 'Web';
            }
        }

        // Deduplicate by normalized email (trim + lowercase);
        // first occurrence is kept, later occurrences get a duplicate error.
        Set<String> seenEmails = new Set<String>();
        List<Lead> leadsToInsert = new List<Lead>();
        List<Integer> originalIndices = new List<Integer>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead l = leads[i];
            String email = l.Email;

            if (String.isNotBlank(email)) {
                String normalized = email.trim().toLowerCase();
                if (seenEmails.contains(normalized)) {
                    result.errorsByIndex.put(
                        i,
                        'Duplicate email in import: ' + normalized
                    );
                    continue;
                }
                seenEmails.add(normalized);
            }

            leadsToInsert.add(l);
            originalIndices.add(i);
        }

        // Single DML statement – allOrNone = false so partial failures
        // don't prevent the rest from being inserted.
        if (!leadsToInsert.isEmpty()) {
            Database.SaveResult[] saveResults = Database.insert(leadsToInsert, false);

            for (Integer j = 0; j < saveResults.size(); j++) {
                Integer origIdx = originalIndices[j];
                Database.SaveResult sr = saveResults[j];

                if (sr.isSuccess()) {
                    result.successCount++;
                    result.insertedIds.add(sr.getId());
                } else {
                    List<String> msgs = new List<String>();
                    for (Database.Error err : sr.getErrors()) {
                        msgs.add(err.getMessage());
                    }
                    result.errorsByIndex.put(origIdx, String.join(msgs, '; '));
                }
            }
        }

        return result;
    }
}
