public class PicklistService {

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;
    }

    public class PicklistServiceException extends Exception {}

    public static List<PicklistService.Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException(
                'Object API name and field API name must not be null or blank.'
            );
        }

        // --- Resolve object (case-insensitive) ---
        Map<String, Schema.SObjectType> globalDesc = Schema.getGlobalDescribe();
        Schema.SObjectType sObjType = null;
        for (String key : globalDesc.keySet()) {
            if (key.equalsIgnoreCase(objectApiName)) {
                sObjType = globalDesc.get(key);
                break;
            }
        }
        if (sObjType == null) {
            throw new PicklistServiceException(
                'SObject not found: ' + objectApiName
            );
        }

        // --- Resolve field (case-insensitive) ---
        Schema.DescribeSObjectResult objDesc = sObjType.getDescribe();
        Map<String, Schema.SObjectField> fieldMap = objDesc.fields.getMap();
        Schema.SObjectField sField = null;
        for (String key : fieldMap.keySet()) {
            if (key.equalsIgnoreCase(fieldApiName)) {
                sField = fieldMap.get(key);
                break;
            }
        }
        if (sField == null) {
            throw new PicklistServiceException(
                'Field not found on object ' + objectApiName + ': ' + fieldApiName
            );
        }

        // --- Validate type ---
        Schema.DescribeFieldResult fieldDesc = sField.getDescribe();
        Schema.DisplayType dtype = fieldDesc.getType();
        if (dtype != Schema.DisplayType.PICKLIST && dtype != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException(
                'Field ' + fieldApiName + ' is not a picklist or multi-select picklist.'
            );
        }

        // --- Collect active values in definition order ---
        List<Schema.PicklistEntry> entries = fieldDesc.getPicklistValues();
        List<PicklistService.Option> options = new List<PicklistService.Option>();
        for (Schema.PicklistEntry entry : entries) {
            if (entry.isActive()) {
                PicklistService.Option opt = new PicklistService.Option();
                opt.value     = entry.getValue();
                opt.label     = entry.getLabel();
                opt.isDefault = entry.isDefaultValue();
                options.add(opt);
            }
        }

        return options;
    }
}
