/**
 * Maintains FB_Open_Pipeline__c (Currency) and FB_Open_Opportunities__c (Number)
 * on Account by recomputing them whenever any open/closed opportunity under that
 * account is inserted, updated, deleted, or undeleted.
 *
 * Recursion guard: the AccountTrigger (after update) pushes a rating onto every
 * open Opportunity, which re-fires this handler.  The static boolean short-circuits
 * that second pass – the pipeline fields were already computed correctly in the
 * first pass, and the AccountTrigger only mutates FB_Account_Rating__c (a field
 * irrelevant to the pipeline calculation).
 */
public with sharing class OpportunityPipelineHandler {

    // ------------------------------------------------------------------
    //  Recursion guard
    // ------------------------------------------------------------------
    @TestVisible
    private static Boolean isRunning = false;

    // ------------------------------------------------------------------
    //  Public entry-points (one per DML operation)
    // ------------------------------------------------------------------

    public static void handleInsert() {
        if (isRunning) return;

        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : Trigger.new) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        recalculate(accountIds);
    }

    public static void handleUpdate() {
        if (isRunning) return;

        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : Trigger.new) {
            Opportunity old = Trigger.oldMap.get(opp.Id);

            // Only recompute if a field relevant to the pipeline changed:
            //   – the opportunity moved to / from an account
            //   – its open/closed status changed  (IsClosed is a formula
            //     derived from StageName)
            //   – its Amount changed
            Boolean relevantChange =
                opp.AccountId != old.AccountId
                || opp.IsClosed != old.IsClosed
                || opp.Amount  != old.Amount;

            if (relevantChange) {
                if (opp.AccountId != null) accountIds.add(opp.AccountId);
                if (old.AccountId != null) accountIds.add(old.AccountId);
            }
        }
        recalculate(accountIds);
    }

    public static void handleDelete() {
        if (isRunning) return;

        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : Trigger.old) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        recalculate(accountIds);
    }

    public static void handleUndelete() {
        if (isRunning) return;

        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : Trigger.new) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        recalculate(accountIds);
    }

    // ------------------------------------------------------------------
    //  Core logic – one bulk SOQL + one bulk DML
    // ------------------------------------------------------------------

    private static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) return;

        isRunning = true;
        try {
            // Seed every affected account at 0 so that accounts which end up
            // with zero open opportunities are explicitly set to 0 / 0
            // (the requirement says "not blank").
            Map<Id, Decimal>  sumMap   = new Map<Id, Decimal>();
            Map<Id, Integer>  countMap = new Map<Id, Integer>();

            for (Id accId : accountIds) {
                sumMap.put(accId,   0);
                countMap.put(accId, 0);
            }

            // Single query – bulk-safe for 200+ records.
            // Null Amount is treated as 0 per the spec.
            for (Opportunity opp : [
                SELECT AccountId, Amount
                FROM   Opportunity
                WHERE  AccountId IN :accountIds
                   AND IsClosed = false
            ]) {
                Decimal amt = (opp.Amount == null) ? 0 : opp.Amount;
                sumMap.put(opp.AccountId,   sumMap.get(opp.AccountId)   + amt);
                countMap.put(opp.AccountId, countMap.get(opp.AccountId) + 1);
            }

            List<Account> accountsToUpdate = new List<Account>();
            for (Id accId : accountIds) {
                accountsToUpdate.add(new Account(
                    Id                        = accId,
                    FB_Open_Pipeline__c       = sumMap.get(accId),
                    FB_Open_Opportunities__c  = countMap.get(accId)
                ));
            }

            update accountsToUpdate;
        } finally {
            isRunning = false;
        }
    }
}
```

### How it works

| Concern | How it is addressed |
|---|---|
| **Recursion via the existing AccountTrigger** | `AccountTrigger` (after update of Account) writes `FB_Account_Rating__c` on open Opportunities, re-firing this Opportunity trigger. The `isRunning` flag is set before the Account `update` and cleared in a `finally` block, so the re-entrant handler call returns immediately. The Account trigger only touches a field irrelevant to the pipeline calculation, so skipping is safe. |
| **Stage / open↔closed changes** | The update handler compares `IsClosed` between old and new; a transition (e.g. Prospecting → Closed Won) triggers a recalculation of both the sum and the count. |
| **Account moves** | Both `opp.AccountId` (new) and `old.AccountId` are added to the set, so both accounts are recomputed. |
| **Amount changes** | The update handler also compares `Amount`; a change recalculates the sum. |
| **Null Amount = 0** | The query loop coerces `null` to `0` before adding. |
| **Last open opp removed → 0 / 0** | Every affected account is seeded at `0` before the query; if no open opps remain, the seed values are written explicitly. |
| **Bulk-safe (200 records)** | One `IN` query + one `update` per trigger invocation regardless of record count. No SOQL/DML inside loops. |
| **Correct after every DML in a transaction** | Each DML fires its own trigger cycle; the flag is set and released within that cycle, so the next DML's handler runs fresh. |

