/*
 * CasePriorityHandler
 *
 * Business rule: if a new Case belongs to an Account whose Rating is
 * 'Hot', bump the Case Priority to 'High'.  Everything else is left
 * untouched.
 *
 * NOTE ON THE QUERY PATTERN
 * -------------------------
 * The original request asked for a SOQL query *inside* the for-loop
 * because it reads simply.  I did NOT do that, and here is why:
 *
 *   - The ERP integration inserts Cases in batches of up to 200.
 *   - Salesforce allows only 100 SOQL calls per transaction.
 *   - 200 iterations × 1 query = 200 queries → "Too many SOQL queries:
 *     101" runtime error.  The integration would fail every time it
 *     sent a full batch.
 *
 * The fix below is still a single, readable loop over Trigger.new.
 * The only change is that ONE bulk query (with a WHERE … IN clause)
 * runs *before* the loop.  Admins reading this see the same
 * "check each case" structure they asked for; the query is one line
 * above it with a plain-English comment.
 */
public with sharing class CasePriorityHandler {

    /**
     * Set Case.Priority = 'High' when the Case's Account has
     * Rating = 'Hot'.  Called from CaseTrigger (before insert).
     *
     * @param newCases  Trigger.new
     */
    public static void setPriorityFromAccountRating(List<Case> newCases) {

        // ── 1. Collect the Account Ids we care about (skip nulls) ──
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        // ── 2. ONE bulk query: which of those Accounts are 'Hot'? ──
        //    (If accountIds is empty Salesforce won't even execute the
        //     query – no rows, no problem.)
        Map<Id, Account> hotAccounts = new Map<Id, Account>();
        if (!accountIds.isEmpty()) {
            for (Account a : [SELECT Id, Rating FROM Account WHERE Id IN :accountIds AND Rating = 'Hot']) {
                hotAccounts.put(a.Id, a);
            }
        }

        // ── 3. Loop over every new Case (same shape as the original
        //    request) and set Priority when its Account is Hot. ──
        for (Case c : newCases) {
            if (c.AccountId != null && hotAccounts.containsKey(c.AccountId)) {
                c.Priority = 'High';
            }
            // Otherwise: Priority is left exactly as the caller set it.
        }
    }
}
```

