import { LightningElement } from 'lwc';
import { getQueueStats } from '@salesforce/apex/QueueController.getQueueStats';

export default class QueueMonitor extends LightningElement {
    _isLoading = false;
    _intervalId = null;
    _stats = null;
    _error = null;

    // --- Lifecycle ---

    connectedCallback() {
        // Start a single 60-second polling loop
        this._intervalId = setInterval(() => this._loadStats(), 60000);

        // Load immediately on insert
        this._loadStats();

        // Listen for visibility changes so hidden tabs skip and re-shown tabs refresh
        document.addEventListener('visibilitychange', this._handleVisibilityChange);
    }

    disconnectedCallback() {
        // Stop polling
        if (this._intervalId != null) {
            clearInterval(this._intervalId);
            this._intervalId = null;
        }

        // Remove the visibility listener so nothing keeps calling Apex
        document.removeEventListener('visibilitychange', this._handleVisibilityChange);

        // Reset internal state so a future re-insertion starts completely fresh
        this._isLoading = false;
        this._stats = null;
        this._error = null;
    }

    // --- Visibility handling ---

    _handleVisibilityChange = () => {
        if (document.visibilityState === 'visible') {
            // Page just became visible: load stats immediately, interval continues on its own
            this._loadStats();
        }
    };

    // --- Data loading ---

    async _loadStats() {
        // Never overlap in-flight requests
        if (this._isLoading) {
            return;
        }

        // Do nothing while the tab is hidden
        if (document.visibilityState === 'hidden') {
            return;
        }

        this._isLoading = true;

        try {
            const stats = await getQueueStats();
            this._stats = stats;
            this._error = null;
        } catch (err) {
            this._error = err.body?.message ?? 'Unknown error';
            this._stats = null;
        } finally {
            this._isLoading = false;
        }
    }

    // --- Getters consumed by the template ---

    get stats() {
        return this._stats;
    }

    get waiting() {
        return this._stats ? this._stats.waiting : null;
    }

    get longestWaitMinutes() {
        return this._stats ? this._stats.longestWaitMinutes : null;
    }

    get error() {
        return this._error;
    }
}
