    get activeDescendantId() {
        if (!this._options || this._options.length === 0) return undefined;
        return `${this._uid}-${this._activeIndex}`;
    }

    get enrichedOptions() {
        if (!this._options || this._options.length === 0) return [];
        return this._options.map((opt, i) => ({
            id: `${this._uid}-${i}`,
            value: opt.value,
            label: opt.label,
            selected: opt.value === this._selectedValue ? 'true' : 'false'
        }));
    }

    // ── Internal helpers ────────────────────────────────────────────
    _syncActiveIndex() {
        if (!this._options || this._options.length === 0) {
            this._activeIndex = 0;
            return;
        }
        const idx = this._options.findIndex(
            (o) => o.value === this._selectedValue
        );
        this._activeIndex = idx >= 0 ? idx : 0;
    }

    _doSelect(index) {
        const opt = this._options[index];
        if (!opt) return;
        if (opt.value === this._selectedValue) return; // no-op

        this._selectedValue = opt.value;
        this.dispatchEvent(
            new CustomEvent('change', { detail: { value: opt.value } })
        );
    }

    // ── Event handlers ──────────────────────────────────────────────
    handleKeydown(event) {
        const HANDLED = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];
        if (!HANDLED.includes(event.key)) return;

        event.preventDefault();

        const len = this._options.length;
        if (len === 0) return;

        switch (event.key) {
            case 'ArrowDown':
                if (this._activeIndex < len - 1) this._activeIndex++;
                break;
            case 'ArrowUp':
