                break;
            case 'Home':
                this._activeIndex = 0;
                break;
            case 'End':
                this._activeIndex = len - 1;
                break;
            case 'Enter':
            case ' ':
                this._doSelect(this._activeIndex);
                break;
        }
    }

    handleClick(event) {
        const value = event.target.dataset.value;
        const idx = this._options.findIndex(
            (o) => String(o.value) === String(value)
