```apex
public class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {

        // Null or empty list → return empty list immediately (no DML)
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        // ── Validate BEFORE any DML ──────────────────────────────────────
        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest req = requests[i];

            if (req.contactId == null) {
                throw new RecurringGiftException(
                    'Request ' + i + ': contact ID is required.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new RecurringGiftException(
                    'Request ' + i + ': amount must be a positive number.');
            }
            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
                throw new RecurringGiftException(
                    'Request ' + i + ': dayOfMonth must be between 1 and 31.');
            }
            if (req.startDate == null) {
                throw new RecurringGiftException(
                    'Request ' + i + ': startDate is required.');
            }
        }

        // ── Build Enhanced Recurring Donation records ────────────────────
        List<npe03__Recurring_Donation__c> rdList =
            new List<npe03__Recurring_Donation__c>();

        for (GiftRequest req : requests) {

            npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c();

            rd.npe03__Contact__c              = req.contactId;
            rd.npe03__Amount__c               = req.amount;
            rd.npe03__Installment_Period__c   = 'Monthly';
            rd.npe03__Installment_Interval__c = 1;

            // Day of month: NPSP interprets 31 as "last day of the month".
            // 29 and 30 are stored as literal calendar days.
            rd.npe03__Day_of_Month__c         = req.dayOfMonth;

            rd.npe03__Effective_Date__c       = req.startDate;
            rd.npe03__Status__c               = 'Active';
            rd.npe03__Payment_Method__c       = req.paymentMethod;

            // Open-ended (null or 0) → leave Installments__c unset.
            // Fixed-length → set the planned number of installments.
            if (req.installments != null && req.installments > 0) {
                rd.npe03__Installments__c = req.installments;
            }

            rdList.add(rd);
        }

        // ── Single DML (all-or-none) ─────────────────────────────────────
        insert rdList;

        // ── Return new Ids in request order ──────────────────────────────
        List<Id> newIds = new List<Id>(rdList.size());
        for (npe03__Recurring_Donation__c rd : rdList) {
            newIds.add(rd.Id);
        }
        return newIds;
    }
}
```

