public class PaymentPlanService {

    public class PaymentPlanException extends Exception {}

    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        // ── Validate numberOfPayments (before any DML) ──
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException(
                'numberOfPayments must be at least 1.'
            );
        }

        // ── Retrieve the opportunity ──
        Opportunity opp = [
            SELECT Id, Amount, IsClosed
            FROM Opportunity
            WHERE Id = :opportunityId
            FOR UPDATE
            LIMIT 1
        ];

        // ── Validate opportunity is not closed (before any DML) ──
        if (opp == null || opp.IsClosed) {
            throw new PaymentPlanException(
                'Cannot schedule installments on a closed opportunity.'
            );
        }

        // ── Query every payment already associated with this opportunity ──
        List<npe01__OppPayment__c> existingPayments = [
            SELECT
                Id,
                npe01__Payment_Amount__c,
                npe01__Paid__c,
                npe01__Written_Off__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
        ];

        // ── Separate history (paid ∪ written-off) from active (replaceable) ──
        List<npe01__OppPayment__c> paymentsToDelete = new List<npe01__OppPayment__c>();
        Decimal historyAmount = 0;

        for (npe01__OppPayment__c p : existingPayments) {
            if (p.npe01__Paid__c || p.npe01__Written_Off__c) {
                // This is a paid or written-off payment – count it toward history
                historyAmount += (p.npe01__Payment_Amount__c != null
                    ? p.npe01__Payment_Amount__c
                    : 0);
            } else {
                // Unpaid AND not written off – will be deleted
                paymentsToDelete.add(p);
