```apex
/**
 * SoftCreditService
 *
 * Manages NPSP partial soft credits for peer-to-peer fundraising.
 * Given a list of SoftCreditRequests, ensures each contact has exactly one
 * OpportunityContactRole (with the requested role) and a corresponding
 * partial soft credit on the target opportunity.
 *
 * Governor-limit aware: ≤ 4 SOQL and ≤ 4 DML for up to 200 requests.
 */
public class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        // Null / empty input is a no-op
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // ── Collect identifiers ───────────────────────────────────────────
        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // ── SOQL 1: Opportunities (needed for validation) ────────────────
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :oppIds
        ]);

        // ── Validate every request BEFORE any DML ─────────────────────────
        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException(
                    'Opportunity not found: ' + String.valueOf(req.opportunityId));
            }
            // Primary-contact guard
            if (opp.npsp__Primary_Contact__c == req.contactId) {
                throw new SoftCreditException(
                    'Cannot create a partial soft credit for the primary contact on Opportunity '
                    + String.valueOf(req.opportunityId));
            }
            // Amount guard
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException(
                    'Partial soft credit amount must be a positive number.');
            }
            if (req.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Partial soft credit amount (' + req.amount
                    + ') exceeds the Opportunity amount (' + opp.Amount + ').');
            }
        }

        // ── SOQL 2: Existing OpportunityContactRoles ──────────────────────
        Map<String, OpportunityContactRole> ocrByKey = new Map<String, OpportunityContactRole>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds
              AND ContactId IN :contactIds
        ]) {
            ocrByKey.put(
                String.valueOf(ocr.OpportunityId) + ':' + String.valueOf(ocr.ContactId),
                ocr
            );
        }

        // ── SOQL 3: Existing Partial Soft Credits ────────────────────────
        Map<String, npsp__Partial_Soft_Credit__c> pscByKey =
            new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id,
                   npsp__Opportunity__c,
                   npsp__Contact__c,
                   npsp__Contact_Role__c,
                   npsp__Amount__c,
                   npsp__Role_Name__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds
              AND npsp__Contact__c IN :contactIds
        ]) {
            pscByKey.put(
                String.valueOf(psc.npsp__Opportunity__c) + ':' + String.valueOf(psc.npsp__Contact__c),
                psc
            );
        }

        // ── Build the OCR upsert set & a lookup for later PSC linking ─────
        List<OpportunityContactRole> ocrsToUpsert = new List<OpportunityContactRole>();
        Map<String, OpportunityContactRole> resolvedOcr =
            new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest req : requests) {
            String key = String.valueOf(req.opportunityId) + ':' + String.valueOf(req.contactId);
            OpportunityContactRole existing = ocrByKey.get(key);

            if (existing == null) {
                // Create a new OCR
                OpportunityContactRole newOcr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId     = req.contactId,
                    Role          = req.role
                );
                ocrsToUpsert.add(newOcr);
                resolvedOcr.put(key, newOcr);
            } else if (existing.Role != req.role) {
                // Update existing OCR so the role matches the request
                existing.Role = req.role;
                ocrsToUpsert.add(existing);
                resolvedOcr.put(key, existing);
            } else {
                // Role already correct – no DML needed, just reference it
                resolvedOcr.put(key, existing);
            }
        }

        // ── DML 1: upsert OpportunityContactRoles ─────────────────────────
        if (!ocrsToUpsert.isEmpty()) {
            upsert ocrsToUpsert;
        }

        // ── Build the PSC upsert set ──────────────────────────────────────
        List<npsp__Partial_Soft_Credit__c> pscsToUpsert =
            new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            String key = String.valueOf(req.opportunityId) + ':' + String.valueOf(req.contactId);
            OpportunityContactRole ocr = resolvedOcr.get(key);
            npsp__Partial_Soft_Credit__c existing = pscByKey.get(key);

            if (existing == null) {
                npsp__Partial_Soft_Credit__c newPsc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c   = req.opportunityId,
                    npsp__Contact__c       = req.contactId,
                    npsp__Contact_Role__c  = ocr.Id,
                    npsp__Amount__c        = req.amount,
                    npsp__Role_Name__c     = req.role
                );
                pscsToUpsert.add(newPsc);
            } else {
                // Update in place – amount, role name, and OCR link
                existing.npsp__Amount__c       = req.amount;
                existing.npsp__Role_Name__c    = req.role;
                existing.npsp__Contact_Role__c = ocr.Id;
                pscsToUpsert.add(existing);
            }
        }

        // ── DML 2: upsert Partial Soft Credits ────────────────────────────
        if (!pscsToUpsert.isEmpty()) {
            upsert pscsToUpsert;
        }
    }
}
```

**Design notes**

| Concern | How it's handled |
|---|---|
| **SOQL budget (≤ 4)** | Exactly 3 queries: Opportunities, OpportunityContactRoles, Partial_Soft_Credits. |
| **DML budget (≤ 4)** | Two `upsert` calls (matching on Id: null → INSERT, populated → UPDATE). New records only get an Id after the first `upsert`, which is required before the PSC list references `npsp__Contact_Role__c`. |
| **Validation before any DML** | All amount / primary-contact checks run in a loop over the input list immediately after the Opportunity query; a `SoftCreditException` short-circuits before any DML statement is reached. |
| **Role alignment** | If the contact's existing OCR has a *different* role (e.g. NPSP's "Household Member"), the OCR is included in the upsert list with its role overwritten, so the contact ends up with exactly one OCR whose `Role` equals the requested role. The PSC's `npsp__Role_Name__c` is kept in sync. |
| **Idempotency** | A second call with the same opp/contact pair finds the existing PSC (and OCR with the correct role) and updates in place rather than creating duplicates. |
| **Bulk safety** | All records are collected into flat lists; no per-request SOQL or DML. Well within the 200-request / 4-query / 4-DML envelope. |

