public with sharing class RecordAccessService {
    private static final Integer BATCH_SIZE = 200;

    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();
        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }
        Id currentUserId = UserInfo.getUserId();
        if (currentUserId == null) {
            return editable;
        }
        List<Id> ids = new List<Id>();
        for (Id rid : recordIds) {
            if (rid != null) {
                ids.add(rid);
            }
        }
        for (Integer start = 0; start < ids.size(); start += BATCH_SIZE) {
            Integer end = start + BATCH_SIZE;
            if (end > ids.size()) {
                end = ids.size();
            }
            List<Id> batch = ids.subList(start, end);
            for (UserRecordAccess ura : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :currentUserId
                AND RecordId IN :batch
            ]) {
                if (ura.HasEditAccess) {
                    editable.add(ura.RecordId);
                }
            }
        }
        return editable;
    }
}
```

