/**
 * Trigger Action that prevents two Contacts on the same Account from sharing
 * an email address (case-insensitive).
 *
 * Registered via Trigger_Action__mdt for BEFORE_INSERT and BEFORE_UPDATE on Contact.
 */
public with sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction {

    public void execute() {
        Boolean isInsert = Trigger.isInsert;
        Boolean isUpdate = Trigger.isUpdate;

        if (!isInsert && !isUpdate) {
            return;
        }

        List<Contact> newRecords = (List<Contact>) Trigger.new;
        Map<Id, Contact> oldMap = Trigger.oldMap;

        // ---- 1. Identify records that need the duplicate-email check ----
        List<Contact> recordsToCheck = new List<Contact>();

        if (isInsert) {
            for (Contact c : newRecords) {
                if (c.AccountId != null && c.Email != null) {
                    recordsToCheck.add(c);
                }
            }
        }

        if (isUpdate) {
            for (Contact c : newRecords) {
                // Only check if Email or AccountId actually changed
                Contact old = oldMap.get(c.Id);
                if (old == null) {
                    continue;
                }

                Boolean emailChanged = c.Email != old.Email;
                Boolean accountChanged = c.AccountId != old.AccountId;

                if ((emailChanged || accountChanged) && c.AccountId != null && c.Email != null) {
                    recordsToCheck.add(c);
                }
            }
        }

        if (recordsToCheck.isEmpty()) {
            return;
        }

        // ---- 2. Build lookup sets for a single SOQL query ----
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();
        Set<Id> selfExclusionIds = new Set<Id>();

        for (Contact c : recordsToCheck) {
            accountIds.add(c.AccountId);
            emails.add(c.Email);
            if (c.Id != null) {
                selfExclusionIds.add(c.Id);
            }
        }

        // ---- 3. One SOQL query per trigger execution ----
        List<Contact> existing;
        if (isInsert) {
            existing = [
                SELECT Id, AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds
                  AND Email IN :emails
            ];
        } else {
            // BEFORE_UPDATE: a contact must never conflict with itself
            existing = [
                SELECT Id, AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds
                  AND Email IN :emails
                  AND Id NOT IN :selfExclusionIds
            ];
        }

        // ---- 4. Map of existing (DB) conflicts keyed by Account+Email ----
        Map<String, Boolean> dbConflict = new Map<String, Boolean>();
        for (Contact c : existing) {
            String key = c.AccountId + '::' + c.Email.toLowerCase();
            dbConflict.put(key, true);
        }

        // ---- 5. Walk recordsToCheck in order; first claim wins ----
        Map<String, Id> batchClaimed = new Map<String, Id>();

        for (Contact c : recordsToCheck) {
            String key = c.AccountId + '::' + c.Email.toLowerCase();

            // Conflicts with an existing record in the database
            if (dbConflict.containsKey(key)) {
                c.addError('Another contact on this account already uses this email address.');
                continue;
            }

