            if (!accountIds.isEmpty()) {
                instance.accountsById = new Map<Id, Account>(
                    [SELECT Id,
                            BillingStreet,
                            BillingCity,
                            BillingPostalCode,
                            BillingCountry,
                            AccountSource
                     FROM Account
                     WHERE Id IN :accountIds]
                );
            }
        }
    }
