public with sharing class AccountRatingService {

    /**
     * Recalculates the Rating field on the given accounts based on their
     * open pipeline (IsClosed = false opportunities).
     *
     *  Hot  – at least one open opp with Amount >= 100 000
     *  Warm – at least one open opp, none that big
     *  Cold – no open opps at all
     *
     * Accepts a list so the trigger can batch all affected accounts into a
     * single async call (avoids the 50-future-per-transaction limit with
     * 200-record CPQ batches).
     */
    @future
    public static void recalculate(List<Id> accountIds) {

        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Bulk-query every open opportunity across all target accounts
        List<Opportunity> openOpps = [
            SELECT AccountId, Amount
            FROM   Opportunity
            WHERE  AccountId IN :accountIds
            AND    IsClosed  =  false
        ];

        // Group by account
        Map<Id, List<Opportunity>> oppsByAccount = new Map<Id, List<Opportunity>>();
        for (Opportunity o : openOpps) {
            if (!oppsByAccount.containsKey(o.AccountId)) {
                oppsByAccount.put(o.AccountId, new List<Opportunity>());
            }
            oppsByAccount.get(o.AccountId).add(o);
        }

        // Build the Account updates
        List<Account> toUpdate = new List<Account>(accountIds.size());
        for (Id accId : accountIds) {
            String rating;
            List<Opportunity> opps = oppsByAccount.get(accId);

            if (opps == null || opps.isEmpty()) {
                rating = 'Cold';
            } else {
                Boolean hasLarge = false;
                for (Opportunity o : opps) {
                    if (o.Amount != null && o.Amount >= 100000) {
                        hasLarge = true;
                        break;
                    }
                }
                rating = hasLarge ? 'Hot' : 'Warm';
            }

            toUpdate.add(new Account(Id = accId, Rating = rating));
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
```

